import type { Quantity } from "../../reality/quantity";
import type { DemandProfile } from "../workload/profiles";
import type { WorkStation, WorkloadInput, StationState } from "../workload/contracts";

export interface ComputeProfile extends Omit<DemandProfile, "schema" | "io" | "stage"> {
  schema: "infraforge-compute-demand/1";
  stage: "compute";
  blockingWait: Quantity<"us">;
  maxCpuParallelism: Quantity<"cores">;
  residentCoverage: "complete-model" | "partial";
  requestResidentBytes?: Quantity<"bytes">;
  activeResidentBytes?: Quantity<"bytes">;
  residentComponents?: Array<{ id: string; owner: "admitted" | "active"; bytes: Quantity<"bytes"> }>;
}
export interface ComputeResource extends Omit<WorkStation, "kind" | "concurrency"> {
  kind: "compute";
  workers: Quantity<"count">;
  scheduler: "capped-equal-fluid/1";
  quota?: { budget: Quantity<"cpu-us">; period: Quantity<"us"> };
  memory: { coverage: "complete-model" | "partial"; baseline?: Quantity<"bytes">; perWorker?: Quantity<"bytes">; retained?: Quantity<"bytes">;
    components?: Array<{ id: string; owner: "process" | "worker"; bytes: Quantity<"bytes"> }>;
    limit?: Quantity<"bytes">; policy: "observe" | "reject-allocation" };
}
export type ComputeIntervention = { id: string; target: string; at: Quantity<"us"> } & (
  { kind: "capacity"; cores: Quantity<"cores"> } |
  { kind: "competitor"; duration: Quantity<"us">; demand: Quantity<"cpu-us">; parallelism: Quantity<"cores"> });
export interface ComputeInput extends Omit<WorkloadInput, "workloadVersion" | "profiles" | "resources"> {
  workloadVersion: "m2c/1";
  profiles: Array<ComputeProfile | DemandProfile>;
  resources: Array<ComputeResource | (WorkStation & { kind: "database" }) | { id: string; kind: "router"; backends: string[] }>;
  interventions: ComputeIntervention[];
}
export interface ComputeState extends StationState {
  compute?: {
    workers: { configured: number; idle: number; runnable: number; blockedWait: number; blockedDependency: number };
    cpu: { capacity: number; runnable: number; receivingShare: number; contended: boolean; paused: boolean; throttled: boolean;
      appCoreUs: number; competitorCoreUs: number; availableCoreUs: number; throttledWallUs: number; unsatisfiedParallelismUs: number;
      quotaRemainingCoreUs: number | null; allocations: Array<{ id: string; cores: number; remainingCoreUs: number }> };
    memory: { ownership: { requests: number; active: number }; knownSubtotalBytes: number; totalResidentBytes: Quantity<"bytes">; components: Record<string, Quantity<"bytes"> >; limitBytes: number | null; comparison: "unknown" | "within" | "exceeds"; policy: string };
    symptoms: string[];
    allocationRejected: number;
  };
}

import { requireKnown } from "../../reality/quantity";
import type { EventClock } from "../time";
import type { Invocation, Receipt, RemoteOutcome } from "../workload/contracts";
import type { ComputeResource, ComputeProfile, ComputeState } from "./contracts";
import { identity } from "../workload/arrivals";
import { cpuScheduler } from "./scheduler";
import { residentMemory } from "./memory";
import type { CausalObserver } from "../workload/causal";

interface Call { work: Invocation; phase: "queued" | "cpu" | "wait" | "dependency" | "finished";
  done(outcome: RemoteOutcome): void; child?: Receipt; cancelWait?: () => boolean; waitRemaining: number; waitSince: number }
export function computeResource(config: ComputeResource, profiles: Map<string, ComputeProfile>, kernel: EventClock,
  send: (target: string, work: Invocation, done: Call["done"]) => Receipt, causal?: CausalObserver, ownedCpu?: ReturnType<typeof cpuScheduler>) {
  const workers = requireKnown(config.workers, "count"), capacity = requireKnown(config.queueCapacity, "count");
  const scheduler = ownedCpu ?? cpuScheduler(config.id, requireKnown(config.cores, "cores"), kernel, config.quota ? { budget: requireKnown(config.quota.budget, "cpu-us"), period: requireKnown(config.quota.period, "us") } : undefined);
  const memory = residentMemory(config, profiles), active = new Map<string, Call>(), queue = new Map<string, Call>();
  let paused = false, received = 0, admitted = 0, rejected = 0, completed = 0, failed = 0, cancelled = 0, allocationRejected = 0, pumping = false;
  let occupancyAt = kernel.now, occupancy = 0;
  const accountOccupancy = () => { occupancy += active.size * (kernel.now - occupancyAt); occupancyAt = kernel.now; };
  const finish = (call: Call, outcome: RemoteOutcome) => {
    if (call.phase === "finished") return;
    if (call.phase === "cpu") scheduler.remove(call.work.callId);
    accountOccupancy(); call.cancelWait?.(); active.delete(call.work.callId); queue.delete(call.work.callId); memory.release(call.work.callId); call.phase = "finished";
    if (outcome === "completed") completed++; else if (outcome === "cancelled") cancelled++; else failed++;
    causal?.({ atUs: kernel.now, kind: "app-terminal", resource: config.id, work: call.work, detail: { outcome } });
    call.done(outcome); pump();
  };
  const scheduleWait = (call: Call) => {
    if (paused) return;
    call.waitSince = kernel.now;
    call.cancelWait = kernel.schedule(kernel.now + call.waitRemaining, 2, identity("blocking-wait", config.id, call.work.callId), () => {
      call.waitRemaining = 0;
      if (config.downstream) {
        call.phase = "dependency";
        const child = { ...call.work, parentCallId: call.work.callId, callId: identity(...JSON.parse(call.work.callId), "dependency", config.downstream) };
        causal?.({ atUs: kernel.now, kind: "app-dependency", resource: config.id, work: child, detail: { target: config.downstream } });
        call.child = send(config.downstream, child, (outcome) => finish(call, outcome));
      } else finish(call, "completed");
    });
  };
  const pump = () => {
    if (pumping) return;
    pumping = true;
    while (!paused && active.size < workers && queue.size) {
      const call = queue.values().next().value!; queue.delete(call.work.callId);
      if (!memory.activate(call.work.callId)) { allocationRejected++; finish(call, "rejected"); continue; }
      accountOccupancy(); active.set(call.work.callId, call); call.phase = "cpu";
      causal?.({ atUs: kernel.now, kind: "app-start", resource: config.id, work: call.work, detail: {} });
      const p = profiles.get(call.work.operation)!;
      scheduler.add({ id: call.work.callId, demand: requireKnown(p.cpu, "cpu-us"), cap: requireKnown(p.maxCpuParallelism, "cores"), done: () => {
        if (call.phase === "finished") return;
        call.phase = "wait"; call.waitRemaining = requireKnown(p.blockingWait, "us"); scheduleWait(call);
      } });
    }
    pumping = false;
  };
  return {
    accept(work: Invocation, done: Call["done"]): Receipt {
      received++;
      const full = queue.size >= capacity && (paused || active.size >= workers);
      const memoryAccepted = !full && memory.acquire(work.callId, work.operation, false);
      if (full || !memoryAccepted) {
        if (!full) allocationRejected++;
        rejected++; causal?.({ atUs: kernel.now, kind: "app-rejected", resource: config.id, work, detail: {} }); done("rejected"); return { admitted: false, cancel: () => "already-finished", state: () => "finished" };
      }
      admitted++;
      causal?.({ atUs: kernel.now, kind: "app-admitted", resource: config.id, work, detail: {} });
      const call: Call = { work, done, phase: "queued", waitRemaining: 0, waitSince: kernel.now };
      queue.set(work.callId, call); pump();
      return { admitted: true, state: () => call.phase === "cpu" || call.phase === "wait" ? "serving" : call.phase === "dependency" ? "waiting" : call.phase,
        cancel: () => { if (call.phase === "finished") return "already-finished"; if (config.cancellation === "unsupported") return "unsupported";
          const child = call.child; finish(call, "cancelled"); child?.cancel(); return "cancelled"; } };
    },
    pause(value: boolean) {
      if (value === paused) throw new Error("Overlapping/unmatched compute pause");
      if (value) for (const call of active.values()) if (call.phase === "wait") { call.waitRemaining -= kernel.now - call.waitSince; call.cancelWait?.(); }
      paused = value; scheduler.pause(value);
      if (!paused) { for (const call of active.values()) if (call.phase === "wait") scheduleWait(call); pump(); }
    },
    setCapacity(cores: number) { scheduler.capacity(cores); },
    abortOwned() { for (const call of [...active.values(), ...queue.values()]) { const child = call.child; finish(call, "rejected"); child?.cancel(); } },
    competitor(id: string, demand: number, parallelism: number) { scheduler.add({ id, demand, cap: parallelism, competitor: true, done: () => {} }); },
    removeCompetitor(id: string) { scheduler.remove(id); },
    measure(): ComputeState {
      const cpu = scheduler.measure(), resident = memory.measure();
      const blockedWait = [...active.values()].filter((c) => c.phase === "wait").length, blockedDependency = [...active.values()].filter((c) => c.phase === "dependency").length;
      const runnable = active.size - blockedWait - blockedDependency;
      return { id: config.id, paused, received, admitted, rejected, completed, failed, cancelled, queued: queue.size, serving: runnable + blockedWait, waiting: blockedDependency,
        consumedCoreUs: cpu.appCoreUs, busySlotUs: occupancy + active.size * (kernel.now - occupancyAt), compute: { workers: { configured: workers, idle: workers - active.size, runnable, blockedWait, blockedDependency }, cpu, memory: resident, allocationRejected,
          symptoms: [ ...(paused || cpu.capacity === 0 ? ["unavailable"] : []), ...(queue.size ? ["backpressured"] : []), ...(cpu.throttled ? ["cpu-throttled"] : []), ...(cpu.contended && !cpu.throttled ? ["cpu-contended"] : []), ...(resident.comparison === "exceeds" ? ["modeled-resident-limit-exceeded"] : []) ] } };
    },
  };
}

import { requireKnown, validateQuantity, type Quantity, type Unit } from "../../reality/quantity";
import type { ComputeInput, ComputeResource, ComputeProfile } from "./contracts";
import { micros } from "../time";
import { COMPUTE_LIMITS } from "./policy";

export function validateCompute(input: ComputeInput) {
  if (input.workloadVersion !== "m2c/1" || input.resources.length > 256 || input.profiles.length > 16384 || input.interventions.length > COMPUTE_LIMITS.interventions) throw new Error("Invalid compute revision/structural budget");
  const ledger = new Map(input.ledger.map((e) => [e.id, e.quantity]));
  const check = (q: Quantity, unit: Unit, min = 0, unknown = false, integer = false) => {
    if (validateQuantity(q).length || q.unit !== unit || (!unknown && q.kind !== "known")) throw new Error(`Unknown/invalid compute ${unit}`);
    for (const id of q.provenance) {
      const e = ledger.get(id);
      if (!e || e.unit !== q.unit || e.kind !== q.kind || (e.kind === "known" && q.kind === "known" && e.value !== q.value) || (e.kind === "range" && q.kind === "range" && (e.min !== q.min || e.max !== q.max)) || (e.kind === "unknown" && q.kind === "unknown" && e.reason !== q.reason)) throw new Error(`Missing exact compute provenance: ${id}`);
    }
    if (q.kind === "known" && (q.value < min || (integer && !Number.isSafeInteger(q.value)))) throw new Error("Invalid compute quantity bounds");
    if (q.kind === "range" && (q.min < min || (integer && (!Number.isSafeInteger(q.min) || !Number.isSafeInteger(q.max))))) throw new Error("Invalid memory bound");
  };
  const components = (parts: Array<{ id: string; owner: string; bytes: Quantity<"bytes"> }>, owners: string[]) => {
    if (parts.length > COMPUTE_LIMITS.memoryComponents || new Set(parts.map((p) => p.id)).size !== parts.length || parts.some((p) => !p.id || !owners.includes(p.owner))) throw new Error("Invalid resident component ownership/budget");
    for (const p of parts) check(p.bytes, "bytes", 0, true, true);
  };
  const defined = <T>(q: T | undefined): q is T => q !== undefined;
  for (const p of input.profiles) if (p.schema === "infraforge-compute-demand/1") {
    check(p.maxCpuParallelism, "cores", Number.MIN_VALUE); check(p.blockingWait, "us", 0, false, true);
    if (!["complete-model", "partial"].includes(p.residentCoverage)) throw new Error("Resident profile coverage required");
    for (const q of [p.requestResidentBytes, p.activeResidentBytes].filter(defined)) check(q, "bytes", 0, true, true);
    components(p.residentComponents ?? [], ["admitted", "active"]);
  }
  const resources = new Map(input.resources.map((r) => [r.id, r]));
  for (const r of input.resources) if (r.kind === "compute") {
    if (!Number.isFinite(requireKnown(r.cores, "cores") * requireKnown(input.horizon, "us"))) throw new Error("Available core-time overflow");
    if (r.scheduler !== "capped-equal-fluid/1" || requireKnown(r.workers, "count") > COMPUTE_LIMITS.workers || !["observe", "reject-allocation"].includes(r.memory.policy)) throw new Error("Unsupported scheduler/workers/memory policy");
    if (!["complete-model", "partial"].includes(r.memory.coverage)) throw new Error("Resident process coverage required");
    for (const q of [r.memory.baseline, r.memory.perWorker, r.memory.retained].filter(defined)) check(q, "bytes", 0, true, true);
    components(r.memory.components ?? [], ["process", "worker"]);
    if (r.memory.limit) check(r.memory.limit, "bytes", 0, false, true);
    const base = [r.memory.baseline, r.memory.perWorker, r.memory.retained, ...(r.memory.components ?? []).map((p) => p.bytes)].filter(defined);
    if (r.memory.policy === "reject-allocation" && r.memory.limit && base.every((q) => q.kind === "known")) {
      const baseline = (r.memory.baseline ? requireKnown(r.memory.baseline, "bytes") : 0) + (r.memory.perWorker ? requireKnown(r.memory.perWorker, "bytes") * requireKnown(r.workers, "count") : 0) + (r.memory.retained ? requireKnown(r.memory.retained, "bytes") : 0) + (r.memory.components ?? []).reduce((sum, p) => sum + requireKnown(p.bytes, "bytes") * (p.owner === "worker" ? requireKnown(r.workers, "count") : 1), 0);
      if (!Number.isSafeInteger(baseline) || baseline > requireKnown(r.memory.limit, "bytes")) throw new Error("Initial modeled memory cannot satisfy hard allocation policy");
    }
    for (const op of input.operations) {
      const p = input.profiles.find((p) => p.id === r.profiles[op.id]);
      if (!p || p.schema !== "infraforge-compute-demand/1") throw new Error("Compute requires a compute-specific demand profile");
      if (!Number.isFinite(requireKnown(p.maxCpuParallelism, "cores") * requireKnown(r.workers, "count") * requireKnown(input.horizon, "us"))) throw new Error("Parallelism integral overflow");
      if (r.memory.policy === "reject-allocation" && (!r.memory.limit || r.memory.coverage !== "complete-model" || p.residentCoverage !== "complete-model" || [...base, p.requestResidentBytes, p.activeResidentBytes, ...(p.residentComponents ?? []).map((p) => p.bytes)].filter(defined).some((q) => q.kind !== "known"))) throw new Error("Hard allocation policy requires complete known modeled memory");
    }
    if (r.quota) {
      check(r.quota.budget, "cpu-us", Number.MIN_VALUE); check(r.quota.period, "us", 1, false, true);
      if (requireKnown(input.horizon, "us") / requireKnown(r.quota.period, "us") > COMPUTE_LIMITS.quotaBoundaries) throw new Error("Quota boundary budget exceeded");
    }
  }
  const ids = new Set<string>(), capacityTimes = new Set<string>();
  for (const i of input.interventions) {
    if (!i.id || ids.has(i.id) || resources.get(i.target)?.kind !== "compute") throw new Error("Invalid compute intervention identity/target"); ids.add(i.id);
    check(i.at, "us", 0, false, true);
    if (i.kind === "capacity") {
      check(i.cores, "cores"); const key = JSON.stringify([i.target, requireKnown(i.at, "us")]);
      if (!Number.isFinite(requireKnown(i.cores, "cores") * requireKnown(input.horizon, "us"))) throw new Error("Capacity integral overflow");
      if (capacityTimes.has(key)) throw new Error("Ambiguous simultaneous capacity changes"); capacityTimes.add(key);
      const resource = resources.get(i.target)!;
      if (resource.kind === "compute") for (const id of Object.values(resource.profiles)) {
        const bound = input.profiles.find((p) => p.id === id)?.validity.ranges.cores, value = requireKnown(i.cores, "cores");
        if (bound && (value < bound.min || value > bound.max)) throw new Error("Unknown capacity intervention outside profile validity domain");
      }
    } else if (i.kind === "competitor") {
      check(i.demand, "cpu-us", Number.MIN_VALUE); check(i.parallelism, "cores", Number.MIN_VALUE); check(i.duration, "us", 1, false, true);
      if (!Number.isFinite(requireKnown(i.parallelism, "cores") * input.interventions.length * requireKnown(input.horizon, "us"))) throw new Error("Competitor parallelism integral overflow");
      micros(requireKnown(i.at, "us") + requireKnown(i.duration, "us"));
    } else throw new Error("Unsupported compute intervention");
  }
}
export const isCompute = (r: ComputeInput["resources"][number]): r is ComputeResource => r.kind === "compute";
export const isComputeProfile = (p: ComputeInput["profiles"][number]): p is ComputeProfile => p.schema === "infraforge-compute-demand/1";

import type { Deliver } from "../compute/run";
import type { EventClock } from "../time";
import { keyedUniform } from "../random";
import type { Invocation, Receipt, RemoteOutcome } from "../workload/contracts";
import type { AsideConfig, DataRequest, DataReply } from "./contracts";
import { DATA_LIMITS } from "./policy";

export function cacheAside(config: AsideConfig, kernel: EventClock, send: Deliver, seed: string) {
  const live = new Map<string, { done(outcome: RemoteOutcome): void; work: Invocation; terminal: boolean }>();
  const fills = new Map<string, Array<(reply: DataReply | undefined) => void>>();
  let received = 0, completed = 0, failed = 0, cacheFailures = 0, fetches = 0, coalesced = 0, invalidations = 0;
  const results: Array<{ root: string; key: string; at: number; version?: number; source: string; ok: boolean }> = []; let omitted = 0;
  return {
    accept(work: Invocation, done: (outcome: RemoteOutcome) => void): Receipt {
      received++; let childSequence = 0; const owner = { work, done, terminal: false }; live.set(work.callId, owner);
      let ordinal = 0; try { const root = JSON.parse(work.rootId) as string[]; const row = root[2]!; ordinal = /^\d+$/.test(row) ? Number(row) : Number(JSON.parse(row).at(-1)) || 0; } catch { /* Non-workload proof roots use the first cycle key. */ }
      const key = (work.message?.request as DataRequest | undefined)?.key ?? config.keys[config.access === "cycle" ? ordinal % config.keys.length : Math.floor(keyedUniform(seed, config.id, work.rootId, "data-key") * config.keys.length)]!;
      const finish = (reply: DataReply | undefined, source: string) => {
        if (owner.terminal) return; owner.terminal = true; live.delete(work.callId); const ok = !!reply?.ok;
        if (ok) completed++; else failed++;
        if (work.message) work.message.response = reply;
        if (results.length < DATA_LIMITS.terminalRows) results.push({ root: work.rootId, key, at: kernel.now, version: reply?.version ?? reply?.rows?.[0]?.version, source, ok }); else omitted++;
        done(ok ? "completed" : "rejected");
      };
      const request = (target: string, body: DataRequest, next: (reply: DataReply | undefined) => void) => {
        const child: Invocation = { ...work, parentCallId: work.callId, callId: JSON.stringify([...JSON.parse(work.callId), "data", config.id, childSequence++, target]), message: { request: body } };
        send(target, child, (outcome) => next(outcome === "completed" ? child.message!.response as DataReply : undefined));
      };
      if (config.operations[work.operation] === "write") {
        fetches++; request(config.database, { kind: "query", key }, (reply) => {
          if (!reply?.ok || !config.invalidateWrites) { finish(reply, "database-write"); return; }
          request(config.cache, { kind: "invalidate", key }, (invalidated) => { if (invalidated?.ok) invalidations++; finish(reply, invalidated?.ok ? "write-invalidated" : "write-invalidation-failed"); });
        });
      } else request(config.cache, { kind: "get", key }, (cached) => {
        if (cached?.hit) { finish(cached, "cache-hit"); return; }
        if (!cached?.ok) { cacheFailures++; if (config.onCacheFailure === "fail") { finish(undefined, "cache-failed"); return; } }
        const ready = (reply: DataReply | undefined) => finish(reply, "database-fetch");
        if (config.coalesce && fills.has(key)) { coalesced++; fills.get(key)!.push(ready); return; }
        const waiters = [ready]; if (config.coalesce) fills.set(key, waiters);
        const complete = (reply: DataReply | undefined) => { if (config.coalesce) fills.delete(key); for (const waiter of waiters) waiter(reply); };
        fetches++; request(config.database, { kind: "query", key }, (reply) => {
          const row = reply?.rows?.find((r) => r.key === key);
          if (!reply?.ok || !row) { complete(reply); return; }
          if (!cached?.ok) { complete(reply); return; } // Failure fallback never fabricates a cache acknowledgement.
          request(config.cache, { kind: "set", key, row, token: cached.token }, () => complete(reply));
        });
      });
      // Application policy detaches from child work; caller cancellation cannot erase a fill.
      return { admitted: true, state: () => owner.terminal ? "finished" : "waiting", cancel: () => owner.terminal ? "already-finished" : "unsupported" };
    },
    pause() { throw new Error("Cache-aside process suspension is outside this policy"); },
    measure: () => ({ id: config.id, paused: false, received, admitted: received, rejected: 0, completed, failed, cancelled: 0, queued: 0, serving: 0, waiting: live.size, consumedCoreUs: 0, busySlotUs: 0 }),
    evidence: () => ({ id: config.id, received, completed, failed, live: live.size, databaseFetches: fetches, cacheFailures, coalescedWaiters: coalesced, fillsInProgress: fills.size, invalidations, results, omitted }),
  };
}

import type { Quantity } from "../../reality/quantity";
import type { ComputeResource } from "../compute/contracts";
import type { NetworkInput } from "../network/contracts";

export interface Row { key: string; version: number; bytes: Quantity<"bytes"> }
export interface Statement {
  kind: "snapshot-read" | "write" | "insert" | "lock-read";
  keys: string[]; cpu: Quantity<"cpu-us">; parallelism: Quantity<"cores">; blockingWait: Quantity<"us">;
  logBytes: Quantity<"bytes">; insertBytes?: Quantity<"bytes">;
}
export interface TransactionPlan { statements: Statement[]; statementTimeout: Quantity<"us">; lockTimeout: Quantity<"us">; transactionTimeout: Quantity<"us">; commitWait: Quantity<"us">; durability: "logical-only" | "authored-log-ack" }
export interface RelationalConfig {
  id: string; kind: "relational"; semantics: "read-committed-keyed/1" | "postgresql-keyed/1";
  execution: ComputeResource; maxSessions: Quantity<"count">; activeTransactions: Quantity<"count">; pendingQueries: Quantity<"count">;
  keys: string[]; initial: Row[]; plans: Record<string, TransactionPlan>;
}
export interface CacheConfig {
  id: string; kind: "cache"; semantics: "keyed-cache/1"; execution: ComputeResource;
  capacity: Quantity<"bytes">; entryOverhead: Quantity<"bytes">; policy: "lru" | "no-eviction";
  ttl: Quantity<"us">; initial: Row[]; commandCpu: Quantity<"cpu-us">;
}
export interface AsideConfig {
  id: string; kind: "cache-aside"; execution: ComputeResource; cache: string; database: string;
  keys: string[]; access: "cycle" | "keyed-uniform"; coalesce: boolean; onCacheFailure: "fail" | "database";
  invalidateWrites: boolean; operations: Record<string, "read" | "write">;
}
export type DataResource = RelationalConfig | CacheConfig | AsideConfig;
export type DataIntervention = { id: string; at: Quantity<"us"> } & (
  { kind: "flush"; target: string } | { kind: "session-capacity"; target: string; sessions: Quantity<"count">; duration: Quantity<"us"> } | { kind: "cpu-capacity"; target: string; cores: Quantity<"cores">; duration: Quantity<"us"> });
export interface DataInput extends Omit<NetworkInput, "workloadVersion" | "resources"> {
  workloadVersion: "m2e/1" | "m2e-pg/1";
  resources: Array<NetworkInput["resources"][number] | DataResource>;
  dataInterventions: DataIntervention[];
}
export interface DataRequest { kind: "get" | "set" | "invalidate" | "query"; key: string; row?: { version: number; bytes: number }; token?: string }
export interface DataReply { ok: boolean; hit?: boolean; key?: string; version?: number; bytes?: number; token?: string; rows?: Array<{ key: string; version: number; bytes: number }>; reason?: string; durable?: boolean }

import { requireKnown, type Quantity, type Unit } from "../../reality/quantity";
import { micros } from "../time";
import type { ComputeInput } from "../compute/contracts";
import type { NetworkInput } from "./contracts";
import { RETRYABLE_FAILURES } from "./contracts";
import { NETWORK_LIMITS as caps } from "./policy";

export function computeAdapter(input: NetworkInput): ComputeInput {
  return { ...input, workloadVersion: "m2c/1", resources: input.resources.map((r) => r.kind === "load-balancer" ? { id: r.id, kind: "router", backends: r.backends } : r) };
}
export function validateNetwork(input: NetworkInput) {
  if (input.workloadVersion !== "m2d/1" || input.links.length > caps.links || input.paths.length > caps.paths || input.networkInterventions.length > caps.interventions) throw new Error("Invalid network revision/structural budget");
  const horizon = requireKnown(input.horizon, "us"), entries = new Map(input.ledger.map((e) => [e.id, e.quantity]));
  const number = <U extends Unit>(q: Quantity<U>, unit: U, min = 0, integer = true) => {
